        [&](const OrderCancelled& e) { release_stock(e.order_id); }
    }, ev);

struct DomainEvent { virtual ~DomainEvent() = default; virtual void accept(Handler&) const = 0; };
struct OrderPlaced : DomainEvent {
    std::int64_t order_id;
    void accept(Handler& h) const override { h.visit(*this); }
};
// registry form:
handlers[typeid(OrderPlaced)].push_back(
    [](const DomainEvent& e) { reserve_stock(static_cast<const OrderPlaced&>(e).order_id); });

boost::signals2::signal<void(const OrderPlaced&)> order_placed;
auto conn = order_placed.connect([](const OrderPlaced& e) { reserve_stock(e.order_id); });

order_placed(OrderPlaced{ order_id, std::chrono::system_clock::now() });
